void    XFTextContent::ToXml(IXFStream *pStrm)
{
//  pStrm->Characters(m_strText);
    OUString sSubString;
    sal_Int32 nIndex = 0;
    sal_Int32 nSize = m_strText.getLength();
    sal_Int32 i,j;
    for (i=0; i<nSize;)
    {
        sSubString = m_strText.copy(i,nSize-i);
        nIndex = sSubString.indexOf("  ");
        if (nIndex == -1)
        {
            pStrm->Characters(sSubString);
            return;
        }
        else
        {
            if (nIndex != 0)
                pStrm->Characters(sSubString.copy(0,nIndex));
            for (j=nIndex+1;j<nSize-i;j++)
            {
                if (sSubString[j] != ' ')
                    break;
            }
            IXFAttrList *pAttrList = pStrm->GetAttrList();
            pAttrList->Clear();
            pAttrList->AddAttribute( u"text:c"_ustr, OUString::number(j-nIndex) );
            pStrm->StartElement( u"text:s"_ustr );
            pStrm->EndElement( u"text:s"_ustr );

            i+=j;
        }
    }
}
